const input = $input.first().json.message.content;

// Extraer valores con expresiones que toleran espacios, saltos de línea o nada
const persona = input.match(/Persona:\s*(.*?)\s*(?:\n|$)/)?.[1]?.trim() ?? null;
const empresa = input.match(/Empresa:\s*(.*?)\s*(?:\n|$)/)?.[1]?.trim() ?? null;
const saludo = input.match(/Saludo:\s*(.*)/)?.[1]?.trim() ?? null;

return [
  {
    json: {
      persona,
      empresa,
      saludo
    }
  }
];

return [
  {
    json: {
      tiempoEspera: Number((Math.random() * 29 + 1).toFixed(2)) // devuelve por ejemplo 20.51
    }
  }
];
